# L1 source-palette anchors: model-specific ochre/purple, measured RNA teal; white canvas.
INK="#272522"; MID="#77726B"; LIGHT="#CAC5BC"; PAPER="#FFFFFF"
MODEL_COL={"DeepSpot2Cell":"#A86334","sCellST":"#6B557F"}
MODEL_LIGHT={"DeepSpot2Cell":"#D6B199","sCellST":"#C1B5CA"}
MEASURED="#236D73"
# L2 classes: near-black hairline; mid-light grey grids; signed negative brick.
RULE="#E0E0E0"; NEG="#A4483A"
fig=plt.figure(figsize=(180/25.4,245/25.4),facecolor=PAPER,dpi=180)
def clean(ax,zero=False):
 ax.set_facecolor(PAPER)
 for s in ["top","right"]:ax.spines[s].set_visible(False)
 for s in ["left","bottom"]:ax.spines[s].set_color(INK)
 ax.tick_params(pad=1.5,colors=INK)
 ax.set_axisbelow(True)
 if zero:ax.axvline(0,color=MID,lw=.5,ls=(0,(2,2)),zorder=0)
def txt(x,y,s,**kw):return fig.text(x,y,s,color=INK,zorder=20,**kw)
def style(model,condition):
 col=MODEL_COL[model]
 if condition=="old_standard":return dict(color=MID,mfc=PAPER,mec=MID,ls="-",lw=.55,alpha=.8)
 if condition=="old_local":return dict(color=col,mfc=col,mec=col,ls="-",lw=.68,alpha=.85)
 return dict(color=col,mfc=PAPER,mec=col,ls=(0,(2,1.2)),lw=.7,alpha=.85)
def condition_points(ax,values,y,model,marker,vertical=False):
 for ci,(cond,val) in enumerate(zip(CONDITIONS,values)):
  st=style(model,cond)
  if vertical:ax.plot([y],[val],marker=marker,ms=3,**st,zorder=4+ci)
  else:ax.plot([val],[y],marker=marker,ms=3,**st,zorder=4+ci)
def get(model,patient,view,condition,band="B4+B5",metric="q"):
 sub=CELL[(CELL.model==model)&(CELL.patient==patient)&(CELL.view==view)&(CELL.condition==condition)&(CELL.band==band)]
 assert len(sub)==1
 return float(sub[metric].iloc[0])

# a-b: five spatial bands remain connected; combined-band endpoint remains separate.
top=fig.add_gridspec(6,2,left=.195,right=.978,bottom=.455,top=.945,hspace=.12,wspace=.12)
n_profiles=n_summary=0
for vi,view in enumerate(VIEWS):
 for mi,model in enumerate(MODELS):
  ax=fig.add_subplot(top[vi,mi]);clean(ax)
  ax.set_xlim(-.23,6.07);ax.set_ylim(-.10,.50);ax.set_yticks([0,.2,.4])
  ax.axhline(0,color=RULE,lw=.5,zorder=0)
  ax.axvline(4.8,color=RULE,lw=.6,zorder=0)
  for pi,patient in enumerate(PATIENTS):
   vals={c:np.array([get(model,patient,view,c,b) for b in BANDS]) for c in CONDITIONS}
   ax.fill_between(BAND_X[:5],vals["old_standard"][:5],vals["old_local"][:5],
                   color=MODEL_LIGHT[model],alpha=.10,lw=0,zorder=1)
   for c in CONDITIONS:
    st=style(model,c)
    ax.plot(BAND_X[:5],vals[c][:5],marker=MARKERS[pi],ms=2.5,mew=.45,**st,zorder=3);n_profiles+=1
    st["ls"]="none"
    ax.plot(BAND_X[5:],vals[c][5:],marker=MARKERS[pi],ms=2.8,mew=.45,**st,zorder=3);n_summary+=1
  if mi==0:ax.set_ylabel(VIEW_LABELS[vi],rotation=0,ha="right",va="center",labelpad=10)
  else:ax.set_yticklabels([]);ax.spines["left"].set_visible(False)
  if vi==0:ax.set_title(model,color=MODEL_COL[model],pad=5)
  ax.set_xticks(BAND_X)
  if vi==5:ax.set_xticklabels(BAND_LABELS,rotation=38,ha="right")
  else:ax.set_xticklabels([])
txt(.018,.975,"a",fontweight="bold",fontsize=9)
txt(.548,.975,"b",fontweight="bold",fontsize=9)
txt(.195,.975,"Noise-corrected correlation, q",fontsize=7,va="top")

# c: attached numerical rails preserve signed patient-mean endpoint changes, not band averaging.
rail=fig.add_gridspec(1,2,left=.195,right=.978,bottom=.346,top=.374,wspace=.12)
for mi,model in enumerate(MODELS):
 ax=fig.add_subplot(rail[0,mi]);ax.set_xlim(-.5,5.5);ax.set_ylim(-.5,1.5)
 for vi,view in enumerate(VIEWS):
  for ri,base in enumerate(["old_standard","non_neighbour"]):
   delta=np.mean([get(model,p,view,"old_local")-get(model,p,view,base) for p in PATIENTS])
   ax.add_patch(Rectangle((vi-.46,1-ri-.36),.92,.72,facecolor=MODEL_LIGHT[model] if delta>=0 else "#D8A69B",edgecolor=PAPER,lw=.3))
   ax.text(vi,1-ri,f"{delta*1000:+.0f}",ha="center",va="center",fontsize=7,zorder=20)
 ax.set_xticks(range(6));ax.set_xticklabels(["Malign.","All","32","64","128","256"])
 ax.set_yticks([1,0]);ax.set_yticklabels(["vs standard","vs non-neighbouring"] if mi==0 else [])
 ax.tick_params(length=0,pad=2)
 for s in ax.spines.values():s.set_visible(False)
txt(.018,.403,"c",fontweight="bold",fontsize=9)
