# Exact-key and no-rescoring checks.
assert len(CELL)==1080 and len(HOT)==30 and len(PAIRED)==360
key=["model","patient","condition","view","population","output_grid_um","band"]
assert not CELL.duplicated(key).any()
assert n_profiles==180 and n_summary==180 and CELL.q.between(-.10,.50).all()
pv=CELL.pivot(index=["model","patient","view","population","output_grid_um","band"],columns="condition",values="q")
ref=PAIRED.set_index(["model","patient","view","population","output_grid_um","band"])
assert np.allclose((pv.old_local-pv.non_neighbour).reindex(ref.index),ref.q_local_minus_non_neighbour)
for t in fig.findobj(Text):t.set_zorder(20)
